function SceneArt(){return <svg className="scene-art" viewBox="0 0 620 330" aria-hidden="true" fill="none"><path d="M42 225 265 150 578 225 345 310Z" fill="var(--taller-panel)" stroke="var(--texto-tenue)"/><path d="M230 196V88a62 62 0 0 1 124 0v108Z" fill="var(--taller-encima)" stroke="var(--texto-tenue)" strokeWidth="2"/><g fill="var(--acento)" stroke="var(--taller-acento)" strokeWidth="1.5">{[[198,214,22],[187,180,21],[192,147,23],[205,116,20],[215,87,23],[241,65,22],[270,51,23],[304,51,21],[334,66,22],[351,93,18]].map(([x,y,r],i)=><circle key={i} cx={x} cy={y} r={r}/>)}</g><ellipse cx="370" cy="225" rx="76" ry="23" fill="var(--superficie)" stroke="var(--texto-tenue)" strokeWidth="2"/><path d="M310 226v43m120-43v43" stroke="var(--texto-tenue)" strokeWidth="6"/></svg>}

function Notice({tone='normal',title,children,actions}: {tone?:string;title:string;children:React.ReactNode;actions?:React.ReactNode}){return <section className="notice" data-tone={tone} role={tone==='error'?'alert':'status'}>{tone==='success'?<Check aria-hidden="true"/>:tone==='warning'?<CloudOff aria-hidden="true"/>:<CircleAlert aria-hidden="true"/>}<div className="notice-body"><h2>{title}</h2><p>{children}</p>{actions&&<div className="group-actions">{actions}</div>}</div></section>}

function App(){
 const m=useMockup(); const profile=useMotionProfile();
 const [lang,setLang]=React.useState(fixture.lang); const t=(es:string,en:string)=>lang==='en'?en:es;
 const [hidden,setHidden]=React.useState(document.hidden);
 const [menu,setMenu]=React.useState(false);const menuRef=React.useRef<HTMLDetailsElement>(null);
 const [query,setQuery]=React.useState(m.state==='no-results'?'Sin coincidencias':'');const [owner,setOwner]=React.useState('all');
 const [page,setPage]=React.useState(m.state==='next-page'?2:1);const [pageError,setPageError]=React.useState(m.state==='next-page-error');
 const [expanded,setExpanded]=React.useState('one');const [name,setName]=React.useState(m.state==='unsaved'?'Escena nueva':fixture.name);
 const [editing,setEditing]=React.useState(false);const [rename,setRename]=React.useState(name); const [formName,setFormName]=React.useState('');
 const [invalid,setInvalid]=React.useState(false);const [busy,setBusy]=React.useState(false); const [feedback,setFeedback]=React.useState('');
 const [detail,setDetail]=React.useState(false);const [newAfterSave,setNewAfterSave]=React.useState(false);const [leaveAfterSave,setLeaveAfterSave]=React.useState(false);
 const pendingAction=React.useRef<''|'new'|'projects'>('');const trigger=React.useRef<HTMLElement|null>(null);const generation=React.useRef(0);const timer=React.useRef<ReturnType<typeof setTimeout>|null>(null);
 const list=['projects','staff'].includes(m.view);const staff=m.view==='staff';const foreign=m.view==='readonly';const noTaller=foreign&&m.state==='no-taller';
 const unsaved=m.state==='unsaved'||!fixture.named;const blocked=['offline','error','conflict','local-error','session-expired'].includes(m.state);
 const showImport=['import-invalid','importing','imported','import-error','import-offer'].includes(m.state);
 const importInvalid=m.state==='import-invalid'; const importBusy=m.state==='importing'||busy;
 React.useEffect(()=>{document.documentElement.lang=lang;fixture.lang=lang},[lang]);
 React.useEffect(()=>{const change=()=>setHidden(document.hidden);document.addEventListener('visibilitychange',change);return()=>document.removeEventListener('visibilitychange',change)},[]);
 React.useEffect(()=>()=>{if(timer.current)clearTimeout(timer.current)},[]);
 React.useEffect(()=>{const fn=(e:KeyboardEvent)=>{if(e.key==='Escape'&&menuRef.current?.open){setMenu(false);menuRef.current.querySelector('summary')?.focus()}};const outside=(e:MouseEvent)=>{if(menuRef.current&&!menuRef.current.contains(e.target as Node))setMenu(false)};document.addEventListener('keydown',fn);document.addEventListener('click',outside);return()=>{document.removeEventListener('keydown',fn);document.removeEventListener('click',outside)}},[]);
 const go=(view:string)=>{m.set('scene','');m.set('view',view);requestAnimationFrame(()=>{document.querySelector<HTMLElement>('h1')?.focus();window.scrollTo(0,0)})};
 const open=(scene:string)=>{trigger.current=document.activeElement as HTMLElement;setInvalid(false);setFormName(scene==='copy'?`${name} (${t('copia','copy')})`:name==='Escena nueva'?'':name);m.set('scene',scene)};
 const close=()=>{setNewAfterSave(false);setLeaveAfterSave(false);m.set('scene','');requestAnimationFrame(()=>{const target=trigger.current;if(target?.isConnected)target.focus();else (document.querySelector<HTMLElement>('.scene-title-button')||document.querySelector<HTMLElement>('.heading .btn')||document.querySelector<HTMLElement>('h1'))?.focus()})};
 const fresh=()=>{fixture.named=false;fixture.draft=false;fixture.name='Escena nueva';m.set('state','unsaved');go('workshop')};
 const requestFresh=()=>{if(busy){pendingAction.current='new';return}if(!list&&(unsaved||blocked||m.state==='saving'))open('new-scene');else fresh()};
 const save=(nextName=name,after=false,retry=false)=>{if(blocked&&!retry){setDetail(true);return}const current=++generation.current;fixture.name=nextName;fixture.draft=true;setBusy(true);setFeedback(t('Guardando…','Saving…'));if(timer.current)clearTimeout(timer.current);timer.current=setTimeout(()=>{if(current!==generation.current)return;fixture.named=true;fixture.draft=false;setBusy(false);const destination=pendingAction.current;pendingAction.current='';if(after||destination==='new'){close();fresh()}else{setName(nextName);close();setFeedback(t('Guardado en tu cuenta','Saved to your account'));m.set('state','normal');if(m.scene==='copy')go('workshop');else if(m.scene==='leave'||leaveAfterSave||destination==='projects')go('projects')}},750)};
 const namedSubmit=(e:React.FormEvent)=>{e.preventDefault();if(!formName.trim()){setInvalid(true);return}save(formName.trim(),newAfterSave,m.scene==='copy')};
 const changeName=(e:React.FormEvent)=>{e.preventDefault();if(!rename.trim())return;setName(rename.trim());setEditing(false);requestAnimationFrame(()=>document.querySelector<HTMLElement>('.scene-title-button')?.focus());if(!unsaved)save(rename.trim());else{fixture.name=rename.trim();setFeedback(t('Sin guardar todavía','Not saved yet'))}};
 const rawDownload=()=>{const a=document.createElement('a');a.href='data:application/json;charset=utf-8,'+encodeURIComponent('{"mock":true,"source":"legacy-scene","version":"unknown"}');a.download='escena-original.mock.json';a.click();setFeedback(t('Original de ejemplo descargado.','Example original downloaded.'))};
 const importScene=()=>{if(importInvalid)return;setBusy(true);setTimeout(()=>{fixture.imported=true;setBusy(false);m.set('scene','');m.set('state','imported')},700)};
 const initialError=['permission-denied','unavailable','session-expired'].includes(m.state);
 const status=busy?t('Guardando…','Saving…'):m.state==='saving'?t('Guardando…','Saving…'):m.state==='conflict'?t('Conflicto','Conflict'):m.state==='offline'?t('Sin guardar · Sin conexión','Not saved · Offline'):m.state==='error'||m.state==='local-error'?t('Sin guardar · Error','Not saved · Error'):unsaved?t('Sin guardar todavía','Not saved yet'):t('Guardado en tu cuenta','Saved to your account');
 const projects=records.filter(r=>(staff||!r.foreign)&&(owner==='all'||(owner==='mine'?!r.foreign:r.foreign))&&r.name.toLocaleLowerCase().includes(query.toLocaleLowerCase().trim()));
 const listRows=page>1?projects:projects.slice(0,staff?3:2);
 function ImportNotice(){return <Notice tone={importInvalid||m.state==='import-error'?'error':m.state==='imported'?'success':'normal'} title={m.state==='imported'?t('Escena importada','Scene imported'):importInvalid?t('No se puede importar esta escena','This scene cannot be imported'):t('Escena guardada en este navegador','Scene saved in this browser')} actions={m.state==='imported'?<Action onClick={()=>go('projects')}>{t('Ver proyectos','View projects')}<ArrowRight aria-hidden="true"/></Action>:<><Action primary={!importInvalid} onClick={()=>open('import')}>{importInvalid?t('Ver explicación','View explanation'):t('Revisar importación','Review import')}</Action>{importInvalid&&<Action onClick={rawDownload}><Download aria-hidden="true"/>{t('Descargar original','Download original')}</Action>}</>}>{m.state==='imported'?t('Se ha creado un proyecto en tu cuenta. El original del navegador se conserva.','One project was created in your account. The browser original is preserved.'):importInvalid?t('Los datos no son compatibles. Conserva el original y descarga una copia para recuperarlo.','The data is incompatible. Keep the original and download a copy to recover it.'):t('Puedes importarla a esta cuenta. Puede pertenecer a otra persona si compartes el dispositivo.','You can import it into this account. It may belong to someone else if you share this device.')}</Notice>}
 function List(){return <>
 <div className="toolbar"><div className="field search"><label htmlFor="project-search">{t('Buscar por nombre','Search by name')}</label><Search aria-hidden="true"/><Input id="project-search" value={query} onChange={e=>{setQuery(e.target.value);setExpanded('');setPage(1);setPageError(false)}} placeholder={t('Buscar por nombre','Search by name')}/></div><div className="end">{staff&&<div className="field"><label htmlFor="owner">{t('Propietario','Owner')}</label><select id="owner" className="native" value={owner} onChange={e=>{setOwner(e.target.value);setExpanded('');setPage(1);setPageError(false)}}><option value="all">{t('Todas las cuentas','All accounts')}</option><option value="mine">{t('Mi cuenta','My account')}</option><option value="other">{t('Cuenta de ejemplo','Example account')}</option></select></div>}<Action onClick={()=>open('import')}>{t('Importar escena del navegador','Import browser scene')}</Action></div></div>
 {showImport&&ImportNotice()}
 {m.state==='loading'?<div className="loading-bands" aria-busy="true"><span className="sr-only" role="status">{t('Cargando proyectos…','Loading projects…')}</span>{[0,1].map(i=><div className="loading-band" key={i}><Skeleton className="skeleton-title"/><Skeleton style={{width:'30%'}}/>{i===0&&<Skeleton className="skeleton-image"/>}</div>)}</div>:m.state==='error'||m.state==='offline'?<Notice tone={m.state==='offline'?'warning':'error'} title={m.state==='offline'?t('Sin conexión','Offline'):t('No se pudieron cargar los proyectos','Could not load projects')} actions={<Action onClick={()=>m.set('state','normal')}>{t('Reintentar','Retry')}</Action>}>{t('Vuelve a intentarlo para cargar los proyectos de tu cuenta.','Try again to load the projects in your account.')}</Notice>:m.state==='empty'||!projects.length?<section className="message"><FolderOpen aria-hidden="true"/><div className="notice-body"><h2>{m.state==='empty'?t('Todavía no tienes proyectos','You have no projects yet'):t('No hay coincidencias','No matches')}</h2><p>{m.state==='empty'?t('Crea una escena en el Taller 3D y guárdala con un nombre.','Create a scene in the 3D workshop and save it with a name.'):t('Prueba con otro nombre o cambia el propietario.','Try another name or change the owner.')}</p>{m.state!=='empty'&&<div><Action onClick={()=>{setQuery('');setOwner('all');m.set('state','normal')}}>{t('Limpiar búsqueda','Clear search')}</Action></div>}</div></section>:<>
 <div className="project-stack">{listRows.map((r,i)=><article className="project-band" key={r.id} data-expanded={expanded===r.id} style={{'--i':i} as React.CSSProperties}><div className="band-head"><div><h2 className="band-title">{r.name}</h2><p className="band-meta">{r.foreign?t('Cuenta de ejemplo · Solo lectura','Example account · Read only'):t('Mi cuenta · Guardado en tu cuenta','My account · Saved to your account')}</p></div><div className="group-actions"><Action className="expand-control" aria-expanded={expanded===r.id} aria-controls={`preview-${r.id}`} onClick={()=>setExpanded(expanded===r.id?'':r.id)}>{expanded===r.id?t('Ocultar escena','Hide scene'):t('Ver escena','View scene')}{expanded===r.id?<ChevronUp aria-hidden="true"/>:<ChevronDown aria-hidden="true"/>}</Action><Action primary={expanded===r.id} aria-label={`${t('Abrir','Open')} ${r.name}`} onClick={()=>{fixture.name=r.name;fixture.named=true;go(r.foreign?'readonly':'workshop')}}>{t('Abrir','Open')}<ArrowRight aria-hidden="true"/></Action></div></div>{expanded===r.id&&<div id={`preview-${r.id}`} className="band-detail"><div className="scene-window" role="img" aria-label={t('Escena de ejemplo: globos, panel y mesa.','Example scene: balloons, panel and table.')}><SceneArt/><span className="scene-note">{t('Vista de escena · Mockup','Scene view · Mockup')}</span></div><div className="project-description"><h3>{t('Escena completa','Complete scene')}</h3><p>{t('Nombre y escena completa disponibles en tu cuenta.','Name and complete scene available in your account.')}</p><details className="what-saves"><summary>{t('Qué se guarda','What is saved')}</summary><p>{t('La conversación con IA y las imágenes generadas permanecen en este navegador.','The AI conversation and generated images stay in this browser.')}</p></details>{r.foreign&&<p>{t('El original de otra cuenta se abre en modo de solo lectura.','Another account’s original opens read only.')}</p>}</div></div>}</article>)}</div>
 <div className="more"><p role="status">{t('Búsqueda en todos los proyectos autorizados.','Search across all authorized projects.')}</p>{pageError?<div className="group-actions"><span className="error-text" role="alert">{t('No se cargó la siguiente página.','Could not load the next page.')}</span><Action onClick={()=>{setPageError(false);setPage(2)}}>{t('Reintentar','Retry')}</Action></div>:<Action disabled={page>1} onClick={()=>setPage(2)}>{page>1?t('No hay más proyectos','No more projects'):t('Cargar más','Load more')}</Action>}</div></>}
 </>}
 function Workshop(){return <>
 {m.state==='conflict'&&<Notice tone="error" title={t('Conflicto de guardado','Save conflict')} actions={<><Action onClick={()=>open('server-version')}>{t('Cargar versión del servidor','Load server version')}</Action><Action primary onClick={()=>open('copy')}>{t('Guardar una copia','Save a copy')}</Action></>}>{t('Otra copia guardó cambios antes. El autoguardado está detenido y tu escena local se conserva.','Another copy saved changes first. Autosave is stopped and your local scene is preserved.')}</Notice>}
 {m.state==='offline'&&<Notice tone="warning" title={t('Sin guardar · Sin conexión','Not saved · Offline')} actions={<Action onClick={()=>save(name,false,true)}>{t('Reintentar al volver a conectar','Retry when reconnected')}</Action>}>{t('Tu escena sigue en este navegador. No está guardada en tu cuenta.','Your scene stays in this browser. It is not saved to your account.')}</Notice>}
 {m.state==='error'&&<Notice tone="error" title={t('No se pudo guardar el proyecto','Could not save the project')} actions={<Action disabled={busy} onClick={()=>save(name,false,true)}>{t('Reintentar','Retry')}</Action>}>{t('Se conserva la escena sin enviar. Reintenta el guardado.','The unsent scene is preserved. Retry saving.')}</Notice>}
 {m.state==='local-error'&&<Notice tone="error" title={t('No pudimos conservar el borrador en este navegador','Could not keep the draft in this browser')} actions={<Action onClick={()=>m.set('state','normal')}>{t('Reintentar respaldo','Retry backup')}</Action>}>{t('Mantén esta vista abierta para conservar el trabajo.','Keep this view open to preserve your work.')}</Notice>}
 {m.state==='recovery'&&<Notice title={t('Hay un borrador de esta cuenta en este navegador','There is a draft from this account in this browser')} actions={<Action onClick={()=>m.set('state','unsaved')}>{t('Recuperar borrador','Recover draft')}</Action>}>{t('Recupéralo antes de continuar con el proyecto.','Recover it before continuing with the project.')}</Notice>}
 {showImport&&ImportNotice()}
 <section className="workshop" aria-label={t('Taller 3D','3D workshop')}><div className="save-header"><div className="scene-identity"><strong>{t('Taller 3D','3D workshop')}</strong><span aria-hidden="true">/</span>{editing?<form className="inline-name" onSubmit={changeName}><Input autoFocus aria-label={t('Nombre de la escena','Scene name')} value={rename} maxLength={120} onChange={e=>setRename(e.target.value)} onKeyDown={e=>{if(e.key==='Escape'){setEditing(false);requestAnimationFrame(()=>document.querySelector<HTMLElement>('.scene-title-button')?.focus())}}}/><Action type="submit" aria-label={t('Confirmar nombre','Confirm name')}><Check aria-hidden="true"/></Action><Action onClick={()=>{setEditing(false);requestAnimationFrame(()=>document.querySelector<HTMLElement>('.scene-title-button')?.focus())}}>{t('Cancelar','Cancel')}</Action></form>:<motion.button transition={profile.spring} whileTap={profile.reduced?undefined:{scale:.965}} className="scene-title-button" onClick={()=>{setRename(name);setEditing(true)}} aria-label={`${t('Cambiar nombre','Rename')}: ${name}`}>{name}<Pencil aria-hidden="true"/></motion.button>}<div className="save-status" role="status" aria-live="polite" data-bad={blocked||unsaved}>{busy||m.state==='saving'?<Loader2 className="status-icon spinner" aria-hidden="true"/>:blocked?<CloudOff className="status-icon" aria-hidden="true"/>:unsaved?<CircleAlert className="status-icon" aria-hidden="true"/>:<Check className="status-icon" aria-hidden="true"/>}{status}</div></div><div className="group-actions"><Action onClick={()=>setDetail(!detail)} aria-expanded={detail}>{t('Qué se guarda','What is saved')}<ChevronDown aria-hidden="true"/></Action><Action primary={!blocked} disabled={m.state==='saving'||busy||m.state==='conflict'} onClick={()=>unsaved?open('first-save'):save()}><Save aria-hidden="true"/>{unsaved?t('Guardar proyecto','Save project'):t('Guardar ahora','Save now')}</Action></div></div>
 {detail&&<div className="save-detail"><p>{t('Se guardan el nombre y la escena completa en tu cuenta. La conversación con IA y las imágenes generadas permanecen en este navegador.','The name and complete scene are saved to your account. The AI conversation and generated images stay in this browser.')}</p>{blocked&&<p className="error-text">{status}</p>}</div>}
 <div className="existing-controls"><div className="group-actions"><Action disabled aria-label={t('Deshacer','Undo')}><Undo2 aria-hidden="true"/></Action><Action disabled aria-label={t('Rehacer','Redo')}><Redo2 aria-hidden="true"/></Action></div><div className="group-actions"><Action onClick={()=>setFeedback(t('Mockup · Herramientas existentes del Taller.','Mockup · Existing workshop tools.'))}><Camera aria-hidden="true"/>{t('Foto realista','Realistic photo')}</Action><Action onClick={()=>setFeedback(t('Mockup · Herramientas existentes del Taller.','Mockup · Existing workshop tools.'))}><ShoppingCart aria-hidden="true"/>{t('Lista de compra','Shopping list')}</Action></div></div><div className="studio-body"><nav className="tool-rail" aria-label={t('Paneles del Taller','Workshop panels')}>{[[Plus,'Añadir'],[Box,'Piezas'],[LayoutGrid,'Plantillas'],[Settings2,'Sala']].map(([Icon,label])=><Action key={label as string} aria-label={label as string} onClick={()=>setFeedback(t('Mockup · Herramientas existentes del Taller.','Mockup · Existing workshop tools.'))}>{React.createElement(Icon as React.ComponentType,{'aria-hidden':true})}</Action>)}</nav><div className="studio-canvas" role="img" aria-label={t('Escena de ejemplo con globos, panel y mesa.','Example scene with balloons, panel and table.')}><SceneArt/><span className="scene-note">{t('Vista de escena · Mockup','Scene view · Mockup')}</span></div><aside className="inspector" aria-label={t('Escena e IA','Scene and AI')}><div className="inspector-tabs"><span>{t('Escena','Scene')}</span><span>IA</span></div><h2>{t('Piezas','Pieces')}</h2><p>{t('Guirnalda','Garland')}</p><p>{t('Panel','Panel')}</p><p>{t('Mesa','Table')}</p><h2>{t('Sala','Room')}</h2><p>{t('Herramientas existentes del Taller','Existing workshop tools')}</p></aside></div>
 <div className="tool-footer"><div className="group-actions"><div className="mobile-tools"><Action onClick={()=>setFeedback(t('Mockup · Herramientas existentes del Taller.','Mockup · Existing workshop tools.'))}><Plus aria-hidden="true"/>{t('Añadir','Add')}</Action><Action onClick={()=>setFeedback(t('Mockup · Herramientas existentes del Taller.','Mockup · Existing workshop tools.'))}><Box aria-hidden="true"/>{t('Piezas','Pieces')}</Action></div><Action onClick={requestFresh}>{t('Escena nueva','New scene')}</Action><Action onClick={requestFresh}>{t('Plantillas','Templates')}</Action><Action onClick={requestFresh}>{t('Abrir en Escena','Open in Scene')}</Action></div><p>{t('La escena nueva empieza sin guardar.','A new scene starts unsaved.')}</p></div></section>
 </>}
 function Readonly(){return <section className="workshop"><div className="foreign-banner"><div><h2 className="band-title">{t('Proyecto de ejemplo','Example project')}</h2><p>{t('Cuenta de ejemplo · Solo lectura','Example account · Read only')}</p></div>{!noTaller&&<Action primary onClick={()=>open('copy')}><Save aria-hidden="true"/>{t('Guardar una copia','Save a copy')}</Action>}</div><div className="readonly-canvas" role="img" aria-label={t('Escena de otra cuenta en modo de solo lectura.','Another account’s scene in read-only mode.')}><SceneArt/><span className="scene-note">{t('Vista de escena · Mockup','Scene view · Mockup')}</span></div><div className="save-detail"><p>{noTaller?t('Sin permiso para usar el Taller 3D. Puedes consultar el proyecto, sin editarlo ni copiarlo.','No permission to use the 3D workshop. You can view the project, without editing or copying it.'):t('El original pertenece a otra cuenta. Una copia se guardará en tu cuenta.','The original belongs to another account. A copy will be saved to your account.')}</p><Action onClick={()=>go('staff')}><ArrowLeft aria-hidden="true"/>{t('Volver a proyectos','Back to projects')}</Action></div></section>}
 const dialogTitle=m.scene==='copy'?t('Guardar una copia','Save a copy'):m.scene==='new-scene'?t('Antes de abrir una escena nueva','Before opening a new scene'):m.scene==='server-version'?t('Cargar versión del servidor','Load server version'):m.scene==='import'?t('Importar escena del navegador','Import browser scene'):t('Guardar proyecto','Save project');
 return <><style>{css}</style><div className="app" data-profile={profile.profile} data-hidden={hidden}>
 <header className="masthead"><div className="brand"><span className="brandmark" aria-hidden="true"><svg viewBox="0 0 16 16" fill="none"><circle cx="8" cy="8" r="5.5" stroke="currentColor" strokeOpacity=".65" strokeWidth="1.2"/><circle cx="8" cy="8" r="1.8" fill="currentColor"/></svg></span>Pictures<span className="company">Sempertex</span></div><div className="header-tools"><label className="language" htmlFor="language">{t('Idioma','Language')}<select className="native" id="language" value={lang} onChange={e=>setLang(e.target.value)}><option value="es">ES</option><option value="en">EN</option></select></label><details className="user-menu" ref={menuRef} open={menu} onToggle={e=>setMenu(e.currentTarget.open)}><summary onClick={e=>{e.preventDefault();setMenu(!menu)}}><UserRound aria-hidden="true"/>{t('Mi cuenta','My account')}<ChevronDown aria-hidden="true"/></summary><div className="menu-options"><p className="muted">{t('Cuenta de ejemplo','Example account')}</p>{['Mi cuenta','Planes','Cerrar sesión'].map(label=><Action key={label} onClick={()=>{setMenu(false);setFeedback(t('Mockup · Destino definido por cuentas-admin@v1 y planes@v1.','Mockup · Destination defined by cuentas-admin@v1 and planes@v1.'))}}>{label==='Mi cuenta'?t(label,'My account'):label==='Planes'?t(label,'Plans'):t(label,'Sign out')}</Action>)}</div></details></div></header>
 <div className="heading"><h1 tabIndex={-1}>{list?t('Proyectos','Projects'):foreign?t('Proyecto · Solo lectura','Project · Read only'):t('Taller 3D','3D workshop')}</h1>{list?<Action primary onClick={fresh}><Plus aria-hidden="true"/>{t('Escena nueva','New scene')}</Action>:<Action onClick={()=>{if(busy){pendingAction.current='projects';return}if(!foreign&&(blocked||unsaved||m.state==='saving')){open('leave');return}go('projects')}}><ArrowLeft aria-hidden="true"/>{t('Proyectos','Projects')}</Action>}</div>
 <nav className="route-nav" aria-label={t('Navegación del producto','Product navigation')}><a href="/3d" aria-current={!list&&!foreign?'page':undefined} onClick={e=>{e.preventDefault();go('workshop')}}>{t('Taller 3D','3D workshop')}</a><a href="/proyectos" aria-current={list||foreign?'page':undefined} onClick={e=>{e.preventDefault();if(busy){pendingAction.current='projects';return}if(!list&&!foreign&&(blocked||unsaved||m.state==='saving'))open('leave');else go('projects')}}>{t('Proyectos','Projects')}</a></nav>
 {feedback&&!busy&&<p role="status" className="notice">{feedback}</p>}
 {initialError?<Notice tone="error" title={m.state==='session-expired'?t('Tu sesión ha terminado','Your session has ended'):m.state==='unavailable'?t('Proyecto no disponible','Project unavailable'):t('No tienes acceso a estos proyectos','You do not have access to these projects')} actions={<Action onClick={()=>{m.set('state','normal');go('projects')}}>{t('Volver a proyectos','Back to projects')}</Action>}>{m.state==='session-expired'?t('Vuelve a iniciar sesión con la misma cuenta para recuperar el borrador.','Sign in again with the same account to recover the draft.'):t('No se muestran datos de proyectos sin autorización.','Project data is not displayed without authorization.')}</Notice>:list?List():foreign?Readonly():Workshop()}
 <footer className="footer"><span>{t('Mockup · Datos y operaciones simulados.','Mockup · Simulated data and operations.')}</span><span>proyectos@v1 · r12 · C</span></footer>
 </div>
 <Dialog open={!!m.scene} onOpenChange={v=>{if(!v&&!busy)close()}}><DialogContent showCloseButton={false} className="project-dialog"><DialogHeader><DialogTitle>{dialogTitle}</DialogTitle><DialogDescription>{m.scene==='import'?t('Destino: Mi cuenta. El original del navegador se conserva.','Destination: My account. The browser original is preserved.'):m.scene==='copy'?t('La copia se guardará en tu cuenta. El original no cambia.','The copy will be saved to your account. The original stays unchanged.'):m.scene==='server-version'?t('Tu borrador local se conserva. El Taller mostrará la escena del servidor.','Your local draft is preserved. The workshop will show the server scene.'):m.scene==='new-scene'||m.scene==='leave'?t('Los cambios pendientes aún no están guardados en tu cuenta.','Pending changes are not yet saved to your account.'):t('Elige un nombre para guardar la escena en tu cuenta. Después se guardará automáticamente.','Choose a name to save the scene to your account. Later changes will save automatically.')}</DialogDescription></DialogHeader>
 {['first-save','copy'].includes(m.scene)?<form className="dialog-form" onSubmit={namedSubmit}><div className="field"><label htmlFor="save-name">{t('Nombre del proyecto','Project name')}</label><Input id="save-name" autoFocus value={formName} onChange={e=>{setFormName(e.target.value);setInvalid(false)}} aria-invalid={invalid} aria-describedby={invalid?'name-error':undefined} maxLength={120} disabled={busy}/>{invalid&&<p id="name-error" className="field-error" role="alert">{t('Escribe un nombre para el proyecto.','Enter a name for the project.')}</p>}</div><p className="dialog-footnote">{t('Se guardan el nombre y la escena completa. La conversación con IA y las imágenes generadas se quedan en este navegador.','The name and complete scene are saved. The AI conversation and generated images stay in this browser.')}</p><div className="dialog-actions"><Action primary type="submit" disabled={busy}>{busy?<><Loader2 aria-hidden="true" className="spinner"/>{t('Guardando…','Saving…')}</>:m.scene==='copy'?t('Guardar una copia','Save a copy'):t('Guardar proyecto','Save project')}</Action><Action disabled={busy} onClick={close}>{t('Cancelar','Cancel')}</Action></div></form>:m.scene==='import'?<div className="dialog-form">{importInvalid||m.state==='import-error'?<div className="dialog-notice" role="alert"><p>{importInvalid?t('Los datos o la versión de la escena no son compatibles. No se ha importado nada.','The scene data or version is incompatible. Nothing has been imported.'):t('No se pudo confirmar la importación. Reintentar no crea otra copia.','The import could not be confirmed. Retrying will not create another copy.')}</p><Action onClick={rawDownload}><Download aria-hidden="true"/>{t('Descargar original','Download original')}</Action></div>:<p>{t('Esta escena puede pertenecer a otra persona si compartes el dispositivo. Solo se importará si aceptas.','This scene may belong to someone else if you share this device. It will only be imported if you accept.')}</p>}<p className="dialog-footnote">{t('La conversación con IA y las imágenes generadas no se importan. El original no se borra ni se modifica, tampoco al rechazar.','The AI conversation and generated images are not imported. The original is never deleted or changed, including when you decline.')}</p><div className="dialog-actions">{!importInvalid&&<Action primary disabled={importBusy} onClick={importScene}>{importBusy?<><Loader2 className="spinner" aria-hidden="true"/>{t('Importando…','Importing…')}</>:t('Importar a mi cuenta','Import to my account')}</Action>}<Action disabled={importBusy} onClick={close}>{t('Ahora no','Not now')}</Action></div></div>:m.scene==='server-version'?<div className="dialog-form"><p>{t('Podrás recuperar tu borrador local desde este navegador. No se mezcla con la versión del servidor.','You can recover your local draft from this browser. It is not merged with the server version.')}</p><div className="dialog-actions"><Action primary onClick={()=>{close();m.set('state','recovery')}}>{t('Cargar versión del servidor','Load server version')}</Action><Action onClick={close}>{t('Cancelar','Cancel')}</Action></div></div>:<div className="dialog-form">{blocked&&<p role="alert" className="error-text">{t('Resuelve el guardado antes de continuar. Tu escena sigue aquí.','Resolve saving before continuing. Your scene stays here.')}</p>}<div className="dialog-actions"><Action primary disabled={blocked||m.state==='saving'} onClick={()=>{if(unsaved){setNewAfterSave(m.scene!=='leave');setLeaveAfterSave(m.scene==='leave');open('first-save')}else save(name,m.scene!=='leave')}}>{t('Guardar y continuar','Save and continue')}</Action>{unsaved&&<Action onClick={()=>{close();m.scene==='leave'?go('projects'):fresh()}}>{t('Descartar escena y continuar','Discard scene and continue')}</Action>}<Action onClick={close}>{t('Cancelar','Cancel')}</Action></div></div>}
 </DialogContent></Dialog>
 </>;
}
mountMockup(App,{
 title:'Proyectos · C · Edición en contexto',motion:'expressive',
 views:[{id:'projects',label:'Mis proyectos'},{id:'staff',label:'Proyectos · Personal'},{id:'workshop',label:'Taller 3D'},{id:'readonly',label:'Proyecto ajeno · Solo lectura'}],
 states:[{id:'normal',label:'Resultados / Guardado'},{id:'loading',label:'Cargando'},{id:'empty',label:'Vacío'},{id:'no-results',label:'Sin coincidencias'},{id:'next-page',label:'Siguiente página'},{id:'next-page-error',label:'Error de siguiente página'},{id:'unsaved',label:'Escena nueva · Sin guardar'},{id:'saving',label:'Guardando'},{id:'offline',label:'Sin conexión'},{id:'error',label:'Error'},{id:'conflict',label:'Conflicto'},{id:'no-taller',label:'Solo lectura · Sin permiso Taller'},{id:'import-offer',label:'Importación disponible'},{id:'import-invalid',label:'Importación inválida'},{id:'importing',label:'Importando'},{id:'imported',label:'Importado'},{id:'import-error',label:'Error de importación'},{id:'recovery',label:'Borrador conservado'},{id:'local-error',label:'Fallo de respaldo local'},{id:'permission-denied',label:'Sin acceso'},{id:'unavailable',label:'No disponible'},{id:'session-expired',label:'Sesión terminada'}],
 scenes:[{id:'',label:'Ninguno'},{id:'first-save',label:'Primer guardado'},{id:'copy',label:'Guardar copia'},{id:'new-scene',label:'Escena nueva'},{id:'leave',label:'Salida con cambios'},{id:'server-version',label:'Versión del servidor'},{id:'import',label:'Importar escena'}],
});
